 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[i][j] == color
                             for i in range(r, r + 3)
                             for j in range(c, c + 3)):
                blocks.append((color, r + 1, c + 1))
    for color, r, c in blocks:
        for j in range(w):
            if out[r][j] == 0:
                out[r][j] = color
        for i in range(h):
            if out[i][c] == 0:
                out[i][c] = color
